from _lib import *
u1=U("running","Opening, agenda and signposting","B1",
 "Open a meeting by welcoming people and stating the purpose, go through the agenda, and use signposts so everyone knows where you are: Let's move on to, Going back to, As you can see.",
 "মিটিং শুরুতে স্বাগত জানিয়ে উদ্দেশ্য বলুন, এজেন্ডা দেখান, আর Let's move on to, As you can see এর মতো সংকেত দিয়ে সবাইকে পথ দেখান।",
 [("Open","Thanks for coming. · Let's get started. · The aim of today's meeting is to…"),("Agenda","There are three items on the agenda. · First, … Then, … Finally, …"),("Signpost","Let's move on to… · Going back to… · As you can see… · To sum up…")],
 [("'Let's' + base verb to start or move on.","Let's + মূল ক্রিয়া।","Let's get started. / Let's move on to the budget."),
  ("'The aim/purpose of this meeting is to' + base verb.","উদ্দেশ্য বোঝাতে is to + verb।","The purpose of this meeting is to agree the launch date."),
  ("Order items: first, then, after that, finally.","ক্রম বোঝাতে first, then, finally।","First, the sales figures. Then, the new hires. Finally, any other business."),
  ("'As you can see' points to a slide.","স্লাইড দেখাতে As you can see।","As you can see on this slide, costs are lower."),
  ("Manage turns: Sorry to interrupt / Could I come in here? / Go ahead.","কথার মাঝে ঢুকতে ভদ্রভাবে।","Sorry to interrupt, but could I add something?")],
 ["let's get started","the aim is to","on the agenda","let's move on to","as you can see","going back to"],
 [("Let's move to next point.","Let's move on to the next point.","Move on to + the.","move on to the next…।"),
  ("Today we will discuss about the budget.","Today we'll discuss the budget.","Discuss has no 'about'.","discuss এর পরে about নয়।"),
  ("As you see in the slide.","As you can see on the slide.","Fixed phrase uses 'can' and 'on'.","As you can see on the slide।")],
 [C("Starting a meeting in Gulshan.","OK, everyone, let's get ___.",["started","start","starting","to start"],"started","Let's get started."),
  C("Purpose.","The aim of today's meeting ___ to plan the Eid campaign.",["is","are","will","for"],"is","The aim is to…"),
  T("Changing topic.","Let's move ___ to the next item on the agenda.","particle",["on"],"Move on to."),
  F("Pick the correct sentence.",["We need to discuss about the timeline.","We need to discuss on the timeline.","We need to discuss the timeline.","We need discussing the timeline."],"We need to discuss the timeline.","Discuss + object."),
  B("আপনারা দেখতে পাচ্ছেন, এই বছর খরচ কমেছে।",["As you can see, costs have gone down this year.","As you are seeing, cost has down this year.","You can see, cost is decreased this year.","As you can see, costs have gone down in this year."],"As you can see, costs have gone down this year.","As you can see + present perfect."),
  C("Interrupting politely.","Sorry to ___, but I have a quick question.",["interrupt","interrupting","disturb you to","stop"],"interrupt","Sorry to interrupt."),
  C("Earlier topic.","___ back to what Sara said, I think the deadline is too tight.",["Going","Go","Gone","To go"],"Going","Going back to…",True),
  T("Agenda.","There are three items ___ the agenda today.","preposition",["on"],"On the agenda.")])
u2=U("charts","Describing charts, summarising and action points","B2",
 "Describe trends with verb + adverb (rose sharply, fell slightly) or adjective + noun (a sharp rise, a slight drop). Use by for the change and to for the end point. Finish with a summary and clear action points: who does what by when.",
 "প্রবণতা বোঝাতে rose sharply বা a sharp rise বলুন। পরিবর্তনের পরিমাণে by, শেষ মানে to। শেষে সারাংশ আর কে কী কবে করবে তা বলুন।",
 [("Verb + adverb","Sales rose sharply. · Costs fell slightly. · Profit remained stable."),("Adj + noun","There was a sharp rise in sales. · a slight drop · a steady increase"),("Wrap up","To sum up, … · So, the action points are… · Rafi will send the report by Friday.")],
 [("Verbs: rise/rose, fall/fell, increase, decrease, remain stable, peak.","rise-rose, fall-fell মনে রাখুন।","Exports fell in March and then peaked in June."),
  ("Adverb with verb, adjective with noun.","ক্রিয়ার সাথে adverb, বিশেষ্যর সাথে adjective।","Prices increased slightly. / There was a slight increase in prices."),
  ("'By' = amount of change; 'to' = new level.","by = কতটা, to = কোথায়।","Sales rose by 10% to 5 crore taka."),
  ("'A rise/fall in' + the thing.","a rise in + বিষয়।","There was a sharp fall in orders."),
  ("Action points: name + will + verb + deadline.","কে, কী, কবে।","Nadia will update the client by Thursday.")],
 ["rose sharply","a slight drop","remained stable","by 10%","to sum up","action points"],
 [("Sales are increased by 10%.","Sales increased by 10%.","'Increase' here is active, not passive.","increase নিজেই ঘটে; passive নয়।"),
  ("There was a sharply rise.","There was a sharp rise.","Noun needs an adjective.","noun এর আগে adjective।"),
  ("Profit raised in May.","Profit rose in May.","'Raise' needs an object; 'rise' does not.","raise কিছুকে তোলা; rise নিজে ওঠা।")],
 [C("Chart.","Sales ___ sharply in the second quarter.",["rose","raised","are risen","rised"],"rose","Rise-rose-risen."),
  C("Noun form.","There was a ___ drop in profit in April.",["slight","slightly","slighting","slighter"],"slight","Adjective + noun."),
  T("Amount of change.","Costs went up ___ 8% last month.","preposition",["by"],"By = amount of change."),
  F("Pick the correct sentence.",["The number of users are increased.","The number of users increased steadily.","The number of users increased steady.","The number of users was increase."],"The number of users increased steadily.","Verb + adverb; active."),
  B("বছরের বাকি সময় দাম স্থিতিশীল ছিল।",["Prices remained stable for the rest of the year.","Prices were stabled rest of the year.","Prices remained stably for the rest of the year.","Price stayed stability rest of year."],"Prices remained stable for the rest of the year.","Remain + adjective."),
  C("New level.","Revenue rose by 20% ___ 3 crore taka.",["to","by","at","until"],"to","To = final level.",True),
  C("Summary.","To ___ up, the campaign was a success but costs were high.",["sum","summary","summarise","sums"],"sum","To sum up."),
  F("Pick the clearest action point.",["Someone should do the report.","The report, maybe next week.","Rafi will send the revised report to the client by Thursday.","Report will be doing soon."],"Rafi will send the revised report to the client by Thursday.","Who, what, when."),
  T("Rise or raise?","We need to ___ prices next year because of higher costs.","verb",["raise","increase"],"Raise + object (prices).",True)])
